commands.command:
/bin/zsh -lc "node --input-type=module -e 'import assert from \"node:assert/strict\";
import { filterOrders } from \"./src/order-filter.mjs\";
import { orders } from \"./src/data/orders.mjs\";
// 直接调用真实筛选函数，核对典型输入，不写入文件。
const cases = [
  { keyword: \"\", status: \"all\", expected: [\"AB-001\", \"CD-002\"] },
  { keyword: \" ALI \", status: \"all\", expected: [\"AB-001\"] },
  { keyword: \"ab-\", status: \"paid\", expected: [\"AB-001\"] },
  { keyword: \"Alice\", status: \"pending\", expected: [] },
  { keyword: \"张\", status: \"pending\", expected: [\"CD-002\"] },
  { keyword: \"   \", status: \"pending\", expected: [\"CD-002\"] }
];
const original = JSON.stringify(orders);
for (const { keyword, status, expected } of cases) {
  const actual = filterOrders(orders, { keyword, status }).map(order => order.id);
  assert.deepEqual(actual, expected);
  console.log(JSON.stringify({ keyword, status, result: actual }));
}
assert.equal(JSON.stringify(orders), original);
console.log(\"6 个筛选案例通过，原始订单数据未变。\");'"
